var i=`caching-algorithms`;var s=39;var a={en:[{id:`T039-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`Caching Algorithms`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Time complexity estimates work as input scales; space complexity estimates additional memory or total storage required.`},{id:`B`,text:`Hash tables optimize key-based lookup under suitable hashing assumptions; trees represent hierarchy or maintain ordered search.`},{id:`C`,text:`Caching trades storage and invalidation complexity for reduced recomputation or I/O.`},{id:`D`,text:`A greedy algorithm repeatedly makes a locally favorable choice without reconsidering earlier decisions.`}]},{id:`T039-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`Caching Algorithms`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Define cache key, value lifetime, capacity, replacement policy, consistency tolerance and eviction trigger.`},{id:`B`,text:`Choose directed or undirected, weighted or unweighted graphs.`},{id:`C`,text:`Track allocations, recursion depth, retained caches and peak working set rather than only loop counts.`},{id:`D`,text:`Comparison sorting commonly requires O(n log n) comparisons in the general case; stable sorts preserve relative order of equal keys.`}]},{id:`T039-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`A team faces this situation: `},{t:`A product catalog can cache category lists for minutes while payment balances should use much stricter freshness rules.`,b:!0},{t:` What is the most appropriate response?`}]}],options:[{id:`A`,text:`A bounded semaphore also prevents an import service from opening thousands of simultaneous connections.`},{id:`B`,text:`A versioned key can invalidate cached category results after updates.`},{id:`C`,text:`Streaming a multi-gigabyte CSV row-by-row uses bounded memory, while loading the full file into an array may exhaust a server even if both approaches are linear in time.`},{id:`D`,text:`A nested category tree can be traversed recursively, while computing the minimum cost to reach each step in a workflow can use DP when paths overlap repeatedly.`}]},{id:`T039-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`Caching Algorithms`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`Concurrency introduces deadlocks, starvation, races and nondeterministic tests.`},{id:`B`,text:`Caching speeds repeated reads but consumes RAM and creates invalidation work.`},{id:`C`,text:`A plausible heuristic is not a correct greedy algorithm.`},{id:`D`,text:`LRU is not automatically optimal; bursty scans can pollute it.`}]},{id:`T039-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`Replacement policies such as LRU, LFU and FIFO make different assumptions about future access.`}]}]},{id:`T039-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`Caching eliminates the need to design cache invalidation and expiry.`}]}]},{id:`T039-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`Caches can hide performance problems and return stale authorization data, so document consistency requirements carefully.`}]}]},{id:`T039-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`Caching Algorithms`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Caching trades storage and invalidation complexity for reduced recomputation or I/O.`},{id:`B`,text:`A shared cache is always consistent with the database without invalidation rules.`},{id:`C`,text:`Define cache key, value lifetime, capacity, replacement policy, consistency tolerance and eviction trigger.`},{id:`D`,text:`An algorithm with lower time complexity always uses less memory.`}]},{id:`T039-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`Caching Algorithms`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Caching eliminates the need to design cache invalidation and expiry.`},{id:`B`,text:`A versioned key can invalidate cached category results after updates.`},{id:`C`,text:`Caches can hide performance problems and return stale authorization data, so document consistency requirements carefully.`},{id:`D`,text:`Dijkstra correctly handles negative edge weights without modification.`}]},{id:`T039-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`A product catalog can cache category lists for minutes while payment balances should use much stricter freshness rules.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Ask an agent to compare buffered and streaming imports. Define realistic memory limits, measure peak use and throughput, and test malformed input and cancellation.`},{id:`B`,text:`Ask an agent to implement stock decrement under concurrent requests, explain linearization points, and verify correctness with stress and database-level tests.`},{id:`C`,text:`Ask an agent to design a bounded product cache with TTL, metrics, stampede prevention and invalidation. Stress-test hot keys and changing records.`},{id:`D`,text:`Have an agent implement interval scheduling and verify its result against brute force for all small generated cases. Request a counterexample to a tempting but incorrect alternative.`}]},{id:`T039-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Which data should never be cached without additional consistency safeguards?`}]}]},{id:`T039-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`A product catalog can cache category lists for minutes while payment balances should use much stricter freshness rules.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`Caching Algorithms`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T039-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`A product catalog can cache category lists for minutes while payment balances should use much stricter freshness rules.`,b:!0},{t:` — propose three checks for `},{t:`Caching Algorithms`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T039-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`A product catalog can cache category lists for minutes while payment balances should use much stricter freshness rules.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T039-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`Caching Algorithms`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`A product catalog can cache category lists for minutes while payment balances should use much stricter freshness rules.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T039-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Алгоритми кешування`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Часова складність оцінює зростання обсягу роботи; просторова — додаткову або загальну пам’ять.`},{id:`B`,text:`Хеш-таблиці оптимізують пошук за ключем за відповідних припущень про хешування; дерева подають ієрархію або підтримують впорядкований пошук.`},{id:`C`,text:`Кешування обмінює пам’ять та складність інвалідації на менші витрати повторних обчислень і I/O.`},{id:`D`,text:`Жадібний алгоритм на кожному кроці обирає локально найкраще рішення без перегляду попереднього.`}]},{id:`T039-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Алгоритми кешування`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Визначте ключ, TTL, місткість, політику витіснення, допустиму неактуальність та умови інвалідації.`},{id:`B`,text:`Оберіть орієнтований чи неорієнтований, зважений чи незважений граф.`},{id:`C`,text:`Враховуйте виділення пам’яті, глибину рекурсії, кеші й піковий робочий набір, а не лише цикли.`},{id:`D`,text:`Сортування порівняннями в загальному випадку потребує O(n log n) порівнянь; стабільний алгоритм зберігає порядок рівних ключів.`}]},{id:`T039-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Команда має таку ситуацію: `},{t:`Каталог може кешувати категорії на хвилини, а платіжні залишки потребують значно суворішої актуальності.`,b:!0},{t:` Яке рішення найдоречніше?`}]}],options:[{id:`A`,text:`Семафор також обмежує кількість одночасних з’єднань імпортера.`},{id:`B`,text:`Версійний ключ допомагає інвалідувати результат після оновлення категорії.`},{id:`C`,text:`Потокова обробка багатогігабайтного CSV використовує обмежену пам’ять, тоді як завантаження всього файлу в масив може вичерпати RAM, хоча час обох рішень лінійний.`},{id:`D`,text:`Вкладене дерево категорій природно обходити рекурсивно; мінімальну вартість досягнення кроків процесу можна обчислювати через DP, якщо підзадачі повторюються.`}]},{id:`T039-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Алгоритми кешування`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Конкурентність створює deadlock, starvation, race condition і нестабільні тести.`},{id:`B`,text:`Кешування пришвидшує повторні читання, але споживає RAM і вимагає інвалідації.`},{id:`C`,text:`Правдоподібна евристика — ще не доведено правильний greedy-алгоритм.`},{id:`D`,text:`LRU не завжди найкращий; масові сканування можуть його засмічувати.`}]},{id:`T039-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`LRU, LFU та FIFO по-різному передбачають майбутні звернення.`}]}]},{id:`T039-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`Кешування усуває потребу проєктувати інвалідацію та строк життя даних.`}]}]},{id:`T039-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Кеш іноді приховує проблеми швидкодії або повертає застарілі права доступу, тому вимоги до узгодженості критичні.`}]}]},{id:`T039-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Алгоритми кешування`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Кешування обмінює пам’ять та складність інвалідації на менші витрати повторних обчислень і I/O.`},{id:`B`,text:`Спільний кеш завжди узгоджений із БД без правил інвалідації.`},{id:`C`,text:`Визначте ключ, TTL, місткість, політику витіснення, допустиму неактуальність та умови інвалідації.`},{id:`D`,text:`Алгоритм із меншою часовою складністю завжди споживає менше пам’яті.`}]},{id:`T039-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Алгоритми кешування`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Кешування усуває потребу проєктувати інвалідацію та строк життя даних.`},{id:`B`,text:`Версійний ключ допомагає інвалідувати результат після оновлення категорії.`},{id:`C`,text:`Кеш іноді приховує проблеми швидкодії або повертає застарілі права доступу, тому вимоги до узгодженості критичні.`},{id:`D`,text:`Алгоритм Дейкстри без змін коректно працює з від’ємними вагами ребер.`}]},{id:`T039-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Каталог може кешувати категорії на хвилини, а платіжні залишки потребують значно суворішої актуальності.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента порівняти буферизований і потоковий імпорт. Задайте ліміт пам’яті, виміряйте пік та пропускну здатність, перевірте пошкоджені файли й скасування.`},{id:`B`,text:`Попросіть агента реалізувати конкурентне списання товару, пояснити точки лінеаризації та довести коректність стрес- і БД-тестами.`},{id:`C`,text:`Попросіть агента спроєктувати обмежений кеш товарів із TTL, метриками, захистом від stampede та інвалідацією. Перевірте гарячі ключі й оновлення записів.`},{id:`D`,text:`Попросіть агента реалізувати вибір інтервалів і перевірити результат повним перебором на малих наборах. Вимагайте контрприклад до привабливої, але неправильної стратегії.`}]},{id:`T039-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Які дані не можна кешувати без додаткових гарантій узгодженості?`}]}]},{id:`T039-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Каталог може кешувати категорії на хвилини, а платіжні залишки потребують значно суворішої актуальності.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Алгоритми кешування`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T039-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Каталог може кешувати категорії на хвилини, а платіжні залишки потребують значно суворішої актуальності.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Алгоритми кешування`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T039-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Каталог може кешувати категорії на хвилини, а платіжні залишки потребують значно суворішої актуальності.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T039-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Алгоритми кешування`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Каталог може кешувати категорії на хвилини, а платіжні залишки потребують значно суворішої актуальності.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var r={slug:i,topicId:39,questions:a};export{r as default,a as questions,i as slug,s as topicId};